import{_ as i,a0 as a,w as p,s as u,ao as r,I as e,a1 as l,A as n,x as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"什麼是黃金鏡像？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是黃金鏡像？ | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是黃金鏡像？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是黃金鏡像？ | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190711 What is a golden image","title":"什麼是黃金鏡像？","tag":"201908","desc":""},"relativePath":"201908/20190711 What is a golden image.md","filePath":"[post].md"}'),g={name:"201908/20190711 What is a golden image.md"};function m(d,t,f,x,T,b){const o=a("Link");return p(),u("div",null,[t[25]||(t[25]=r('<h1 id="什麼是黃金鏡像" tabindex="-1">什麼是黃金鏡像？ <a class="header-anchor" href="#什麼是黃金鏡像" aria-label="Permalink to “什麼是黃金鏡像？”">​</a></h1><blockquote><p>正在開發一個將廣泛分發的項目嗎？瞭解一下黃金鏡像吧，以便在出現問題時輕鬆恢復到“完美”狀態。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/08/184231ivv745lukchbrhul.jpg" alt=""></p><p>如果你正在從事於質量保證、系統管理或媒體制作（沒想到吧），你可能聽説過<ruby>正式版<rt>gold master</rt></ruby>這一術語的某些變體，如<ruby>黃金鏡像<rt>golden image</rt></ruby>或<ruby>母片<rt>master image</rt></ruby>等等。這個術語已經進入了每個參與創建<strong>完美</strong>模具的人的集體意識，然後從該模具中產生許多複製品。母片或黃金鏡像就是：一種虛擬模具，你可以從中打造可分發的模型。</p><p>在媒體制作中，這就是所有人努力開發母片的過程。這個最終產品是獨一無二的。它看起來和聽起來像是可以看和聽的最好的電影或專輯（或其他任何東西）。可以製作和壓縮該母片的副本併發送給急切的公眾。</p><p>在軟件中，與該術語相關聯的也是類似的意思。一旦軟件經過編譯和一再測試，完美的構建成果就會被聲明為<strong>黃金版本</strong>，不允許對它進一步更改，並且所有可分發的副本都是從此母片生成的（當軟件是用 CD 或 DVD 分發時，這實際上就是母盤）。</p><p>在系統管理中，你可能會遇到你的機構所選的操作系統的黃金鏡像，其中的重要設置已經就緒，如安裝好的虛擬專用網絡（VPN）證書、設置好的電子郵件收件服務器的郵件客户端等等。同樣，你可能也會在虛擬機（VM）的世界中聽到這個術語，其中精心配置了虛擬驅動器的黃金鏡像是所有克隆的新虛擬機的源頭。</p><h3 id="gnome-boxes" tabindex="-1">GNOME Boxes <a class="header-anchor" href="#gnome-boxes" aria-label="Permalink to “GNOME Boxes”">​</a></h3><p>正式版的概念很簡單，但往往忽視將其付諸實踐。有時，你的團隊很高興能夠達成他們的目標，但沒有人停下來考慮將這些成就指定為權威版本。在其他時候，沒有簡單的機制來做到這一點。</p><p>黃金鏡像等同於部分歷史的保存和提前備份計劃。一旦你製作了一個完美的模型，無論你正在努力做什麼，你都應該為自己保留這項工作，因為它不僅標誌着你的進步，而且如果你繼續工作時遇到問題，它就會成為一個後備。</p>',10)),e("p",null,[l(o,{href:"https://wiki.gnome.org/Apps/Boxes"},{default:n(()=>[...t[0]||(t[0]=[s("GNOME Boxes",-1)])]),_:1}),t[2]||(t[2]=s("，是隨 GNOME 桌面一起提供的虛擬化平台，可以用作簡單的演示用途。如果你從未使用過 GNOME Boxes，你可以在 Alan Formy-Duval 的文章 ",-1)),l(o,{href:"https://opensource.com/article/19/5/getting-started-gnome-boxes-virtualization"},{default:n(()=>[...t[1]||(t[1]=[s("GNOME Boxes 入門",-1)])]),_:1}),t[3]||(t[3]=s("中學習它的基礎知識。",-1))]),t[26]||(t[26]=e("p",null,"想像一下，你使用 GNOME Boxes 創建虛擬機，然後將操作系統安裝到該 VM 中。現在，你想要製作一個黃金鏡像。GNOME Boxes 已經率先攝取了你的安裝快照，可以作為更多的操作系統安裝的黃金鏡像。",-1)),t[27]||(t[27]=e("p",null,[s("打開 GNOME Boxes 並在儀表板視圖中，右鍵單擊任何虛擬機，然後選擇"),e("strong",null,"屬性"),s("。在"),e("strong",null,"屬性"),s("窗口中，選擇"),e("strong",null,"快照"),s("選項卡。由 GNOME Boxes 自動創建的第一個快照是“Just Installed”。顧名思義，這是你最初安裝到虛擬機上的操作系統。")],-1)),t[28]||(t[28]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/uploads/snapshots.jpg",alt:"The Just Installed snapshot, or initial golden image, in GNOME Boxes.",title:"The Just Installed snapshot, or initial golden image."})],-1)),t[29]||(t[29]=e("p",null,"如果你的虛擬機變成了你不想要的狀態，你可以隨時恢復為“Just Installed”鏡像。",-1)),e("p",null,[t[5]||(t[5]=s("當然，如果你已經為自己調整了環境，那麼在安裝後恢復操作系統將是一個極大的工程。這就是為什麼虛擬機的常見工作流程是：首先安裝操作系統，然後根據你的要求或偏好修改它，然後拍攝快照，將該快照聲明為配置好的黃金鏡像。例如，如果你使用虛擬機進行 ",-1)),l(o,{href:"https://opensource.com/business/16/8/flatpak"},{default:n(()=>[...t[4]||(t[4]=[s("Flatpak",-1)])]),_:1}),t[6]||(t[6]=s(" 打包，那麼在初始安裝之後，你可以添加軟件和 Flatpak 開發工具，構建工作環境，然後拍攝快照。創建快照後，你可以重命名該虛擬機以指示其真實用途。",-1))]),t[30]||(t[30]=r('<p>要重命名虛擬機，請在儀表板視圖中右鍵單擊其縮略圖，然後選擇<strong>屬性</strong>。在<strong>屬性</strong>窗口中，輸入新名稱：</p><p><img src="https://opensource.com/sites/default/files/uploads/boxes-rename_0.jpg" alt="Renaming your VM image in GNOME Boxes." title="Renaming your virtual machine in GNOME Boxes."></p><p>要克隆你的黃金映像，請右鍵單擊 GNOME Boxes 界面中的虛擬機，然後選擇<strong>克隆</strong>。</p><p><img src="https://opensource.com/sites/default/files/uploads/boxes-clone.jpg" alt="Cloning your golden image in GNOME Boxes." title="Cloning your golden image in GNOME Boxes."></p><p>你現在可以從黃金映像的最新快照中克隆了。</p><h3 id="黃金鏡像" tabindex="-1">黃金鏡像 <a class="header-anchor" href="#黃金鏡像" aria-label="Permalink to “黃金鏡像”">​</a></h3>',6)),e("p",null,[t[8]||(t[8]=s("很少有學科無法從黃金鏡像中受益。無論你是在 ",-1)),l(o,{href:"https://git-scm.com"},{default:n(()=>[...t[7]||(t[7]=[s("Git",-1)])]),_:1}),t[9]||(t[9]=s(" 中標記版本、在 Boxes 中拍攝快照、出版原型黑膠唱片、打印書籍以進行審核、設計用於批量生產的絲網印刷、還是製作文字模具，到處都是各種原型。這只是現代技術讓我們人類更聰明而不是更努力的另一種方式，因此為你的項目製作一個黃金鏡像，並根據需要隨時生成克隆吧。",-1))]),t[31]||(t[31]=e("hr",null,null,-1)),e("p",null,[t[11]||(t[11]=s("via: ",-1)),l(o,{href:"https://opensource.com/article/19/7/what-golden-image"},{default:n(()=>[...t[10]||(t[10]=[s("https://opensource.com/article/19/7/what-golden-image",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=s("作者：",-1)),l(o,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[12]||(t[12]=[s("Seth Kenlon",-1)])]),_:1}),t[17]||(t[17]=s(" 選題：",-1)),l(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[13]||(t[13]=[s("lujun9972",-1)])]),_:1}),t[18]||(t[18]=s(" 譯者：",-1)),l(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[14]||(t[14]=[s("wxy",-1)])]),_:1}),t[19]||(t[19]=s(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[15]||(t[15]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=s("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[20]||(t[20]=[s("LCTT",-1)])]),_:1}),t[23]||(t[23]=s(" 原創編譯，",-1)),l(o,{href:"https://linux.cn/"},{default:n(()=>[...t[21]||(t[21]=[s("Linux中國",-1)])]),_:1}),t[24]||(t[24]=s(" 榮譽推出",-1))])])}const B=i(g,[["render",m]]);export{C as __pageData,B as default};
